// English Basics — 20 grammar topics for Class 5, lesson metadata + question
// generators. Each topic builds an EASY (15), MEDIUM (15) and CHALLENGE (10)
// question bank on demand, so the same lesson never feels repetitive and a
// real API can serve the same data later.

const q = (question, options, answer, explanation) => ({ question, options, answer, explanation })

// Shuffle at runtime inside the component; banks here stay deterministic for tests.
export const shuffle = (arr) => {
  const a = arr.slice()
  for (let i = a.length - 1; i > 0; i -= 1) {
    const j = Math.floor(Math.random() * (i + 1))
    ;[a[i], a[j]] = [a[j], a[i]]
  }
  return a
}

