// Builds the full bank for a topic: 15 easy + 15 medium + 10 challenge
// (first 15 → easy, next 15 → medium, remaining → challenge).
export const getGrammarBank = (topicId) => {
  const fn = BANKS[topicId]
  if (!fn) return []
  return fn().map((item, i) => ({
    ...item,
    id: `${topicId}-${i + 1}`,
    topicId,
    difficultyKey: i < 15 ? 'easy' : i < 30 ? 'medium' : 'challenge',
  }))
}